def conv_b(aa,bb):
    ch=""
    while aa!=0:
        r=aa%bb
        if r<10:
            c=str(r)
        else:
            c=chr(r+55)
        ch=c+ch
        aa=aa//bb
    return ch

print(conv_b(123,5))

